function t4(s,a,b,za,zb){return item('N4',s,a,b,za,zb)}
function t3(s,a,b,za,zb){return item('N3',s,a,b,za,zb)}
function t2(s,a,b,za,zb){return item('N2',s,a,b,za,zb)}
function t1(s,a,b,za,zb){return item('N1',s,a,b,za,zb)}

